sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.guest-ai-page {
  max-width: 700px;
  margin: 30px auto;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
  overflow: hidden;
}

.guest-ai-header {
  background: #2c3e50;
  color: #ffffff;
  padding: 20px 25px;
}

.hotel-info h2 {
  margin: 0 0 5px 0;
  font-size: 22px;
}

.hotel-info p {
  margin: 0;
  opacity: 0.85;
}

.guest-info {
  margin-top: 12px;
  font-size: 14px;
}

.guest-ai-chat-area {
  min-height: 500px;
  padding: 25px;
}

.guest-ai-chat-area h4 {
  margin-top: 0;
  font-size: 18px;
}

.guest-ai-chat-area p {
  color: #718096;
}

sp_widget.script:
(function() {

    data.hotelName = $sp.getParameter('hotel_name') || 'Grand Hyatt';
    data.city = $sp.getParameter('city') || 'San Diego';
    data.country = $sp.getParameter('country') || 'USA';
    data.roomNumber = $sp.getParameter('room_id') || 'Unknown';
    data.guestName = $sp.getParameter('guest_name') || 'Valued Guest';

})();
